#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
#
# Kaggle training wizard for the UAV YOLO study. Run it from inside the repo, in Git Bash (Windows),
# Terminal (macOS) or any Linux shell:
#
#   bash study/kaggle/wizard.sh          # once per person: computer check -> Kaggle -> first training session
#   bash study/kaggle/wizard.sh next     # after EVERY training session: bring results home, start the next one
#   bash study/kaggle/wizard.sh token    # only if Kaggle stops accepting your API token: paste a new one
#
# It remembers your answers and how far you got in study/kaggle/.env.kaggle (git-ignored), so you can close
# it during a long wait and run the same command again later. The written guide is study/kaggle/README.md.

GUIDE_URL="https://github.com/Sri-Krishna-V/uav-yolo-edge-compression/blob/main/study/kaggle/README.md"

# ── Look and feel ─────────────────────────────────────────────────────────

gap()     { printf '\n'; }
heading() { printf '\n  %s%s%s\n' "$BOLD" "$1" "$RESET"; }
why()     { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
ok()      { printf '  %s✓ %s%s\n' "$GREEN" "$1" "$RESET"; }
bad()     { printf '  %s✗ %s%s\n' "$YELLOW" "$1" "$RESET"; }
# num N "text": a numbered action, with a blank line before it so steps never run together.
num()     { printf '\n  %s%s%s.%s %s\n' "$BOLD" "$BLUE" "$1" "$RESET" "$2"; }
# more "text": a second line under the step above.
more()    { printf '     %s\n' "$1"; }
key()     { printf '%s%s%s' "$BOLD" "$1" "$RESET"; }

# section "Title" "One line on why this stage exists": stage header, progress bar, reason.
section() {
  stage "$1"
  local width=36 filled i done_part="" todo_part=""
  filled=$(( _STAGE_INDEX * width / TOTAL_STAGES ))
  for (( i = 0; i < width; i++ )); do
    if (( i < filled )); then done_part+="━"; else todo_part+="─"; fi
  done
  printf '  %s%s%s%s%s\n' "$GREEN" "$done_part" "$DIM" "$todo_part" "$RESET"
  [[ -z "${2:-}" ]] || { gap; why "$2"; }
}

# must "question": a yes/no check that only moves on at yes. Closed input (Ctrl-D) stops the wizard.
must() {
  local reply
  gap
  while :; do
    printf '  %s? %s%s [y/N] ' "$YELLOW" "$1" "$RESET"
    if ! read -r reply; then
      gap; warn "Stopped. Run the same command again to continue from this stage."
      exit 1
    fi
    [[ "$reply" =~ ^[Yy] ]] && return 0
    warn "No rush. Fix it in the browser, then answer again."
  done
}

# come_back MINUTES: the clock time a wait of that length ends.
come_back() {
  date -d "+$1 min" +%H:%M 2>/dev/null || date -v+"$1"M +%H:%M 2>/dev/null || printf 'in about %s min' "$1"
}

# wrap_up: the closing screen, without the list of internal keys the wizard saved for itself.
wrap_up() { WRITTEN_ENV=(); finish; }

# remember KEY VALUE: save quietly (internal progress, not something the person typed).
remember() { write_env "$1" "$2" >/dev/null; }

# saved KEY VALUE: save something the person typed, with a short confirmation.
saved() { write_env "$1" "$2" >/dev/null; ok "Saved."; }

# sync_repo: bring this copy up to date with GitHub, replaying any commits not pushed yet on top. An untracked copy
# of a file GitHub now has (a record imported here that someone else then committed) makes git refuse to update,
# so copies identical to GitHub's are removed first. Returns 1 if GitHub could not be reached, 2 if this copy and
# GitHub's could not be combined (a file differs).
sync_repo() {
  local f
  # A rebase the person started is theirs to finish: the --abort below must only ever undo the wizard's own.
  [[ -d "$(git rev-parse --git-path rebase-merge)" || -d "$(git rev-parse --git-path rebase-apply)" ]] && return 2
  git fetch -q >/dev/null 2>&1 || return 1
  while IFS= read -r f; do
    if [[ "$(git rev-parse -q --verify "@{u}:$f" 2>/dev/null)" == "$(git hash-object -- "$f")" ]]; then rm -f -- "$f"; fi
  done < <(git ls-files --others --exclude-standard -- study/verification)
  git rebase -q --autostash "@{u}" >/dev/null 2>&1 && return
  git rebase --abort >/dev/null 2>&1
  return 2
}

# push_commit: push the commit just made, after replaying it on top of whatever the teammate pushed meanwhile.
# Commits of this computer's that are not on GitHub yet go too, so they are shown and must be confirmed.
# On failure, says why and returns 1.
push_commit() {
  local others rc=0
  others=$(git log --format='%h %s' "@{u}..HEAD~1" 2>/dev/null || true)
  if [[ -n "$others" ]]; then
    warn "Pushing also sends these commits of yours, which are not on GitHub yet:"
    printf '%s\n' "$others" | sed 's/^/        /'
    confirm "Push them too?" || { warn "Not pushed."; return 1; }
  fi
  sync_repo || rc=$?
  case "$rc" in
    1) warn "Could not reach GitHub."; return 1 ;;
    2) warn "GitHub has a different version of one of these files, so the wizard cannot combine them."; return 1 ;;
  esac
  git push -q && return
  warn "The push failed: no access, or the wrong GitHub account (two accounts? run: gh auth switch)."
  return 1
}

# ── Doing things ──────────────────────────────────────────────────────────

# open_url URL: replaces the library's version. On Windows, explorer.exe reports failure even when it has
# opened the page, so the library's version warned "couldn't open a browser" in Git Bash every time.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  case "$(uname -s)" in
    MINGW*|MSYS*|CYGWIN*) explorer.exe "$url" >/dev/null 2>&1 || true; return ;;
  esac
  { if   command -v wslview  >/dev/null 2>&1; then wslview "$url"
    elif command -v xdg-open >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open     >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# python_bin prints the name of this machine's Python 3.9+, or fails.
python_bin() {
  local bin
  for bin in python3 python py; do
    if command -v "$bin" >/dev/null 2>&1 && "$bin" -c "import sys; sys.exit(sys.version_info < (3, 9))" >/dev/null 2>&1; then
      printf '%s' "$bin"
      return 0
    fi
  done
  return 1
}

has_python() { python_bin >/dev/null; }

# helper runs the repo's Kaggle helper with whichever Python this machine has (standard library only).
helper() {
  local bin
  if ! bin=$(python_bin); then
    warn "No Python 3.9+ found. Install it from https://www.python.org/downloads/ and run the wizard again."
    exit 1
  fi
  "$bin" -X utf8 study/kaggle/session.py "$@"
}

# The Kaggle CLI lives in its own small Python environment inside the repo (git-ignored), so it needs nothing on
# PATH and leaves the person's own Python alone.
CLI_DIR="study/kaggle/.kaggle-cli"

cli_python() {
  case "$(uname -s)" in
    MINGW*|MSYS*|CYGWIN*) printf '%s' "$CLI_DIR/Scripts/python.exe" ;;
    *)                    printf '%s' "$CLI_DIR/bin/python" ;;
  esac
}

# install_cli: create that environment and install the kaggle package, once.
install_cli() {
  if [[ -x "$(cli_python)" ]] && "$(cli_python)" -c "import kaggle.cli" >/dev/null 2>&1; then return 0; fi
  say "Installing the Kaggle command-line tool. This takes about a minute and happens once..."
  if "$(python_bin)" -m venv "$CLI_DIR" && "$(cli_python)" -m pip install -q --disable-pip-version-check kaggle; then
    ok "Installed."
  else
    bad "Could not install the Kaggle command-line tool."
    why "Ubuntu or Debian: install venv first (sudo apt install python3-venv), then run the wizard again."
    rm -rf "$CLI_DIR"
    stuck; exit 1
  fi
}

# kaggle_cli ARGS: run the Kaggle CLI, signed in with the saved token and nothing else.
#   KAGGLE_CONFIG_DIR is an empty folder of our own. The CLI silently ignores a bad token and falls back to any
#   ~/.kaggle/kaggle.json, so without this a wrong token can pass the check in ask_token.
#   -X utf8, because the CLI saves the session log with Python's default file encoding, which on Windows
#   (cp1252) cannot write the log's emoji.
kaggle_cli() {
  mkdir -p "$CLI_DIR/config"
  KAGGLE_API_TOKEN="$KAGGLE_TOKEN" KAGGLE_CONFIG_DIR="$CLI_DIR/config" PYTHONIOENCODING=utf-8 \
    "$(cli_python)" -X utf8 -m kaggle "$@"
}

# notebook_ref URL: owner/notebook-slug, the name the Kaggle CLI uses for a notebook.
notebook_ref() { printf '%s' "${1#*kaggle.com/code/}"; }

has_clipboard() {
  command -v clip.exe >/dev/null 2>&1 || command -v pbcopy >/dev/null 2>&1 ||
    command -v wl-copy >/dev/null 2>&1 || command -v xclip >/dev/null 2>&1
}

clipboard() {
  if   command -v clip.exe >/dev/null 2>&1; then clip.exe
  elif command -v pbcopy   >/dev/null 2>&1; then pbcopy
  elif command -v wl-copy  >/dev/null 2>&1; then wl-copy
  elif command -v xclip    >/dev/null 2>&1; then xclip -selection clipboard
  else return 1; fi
}

# copy_cell TASK: write the notebook cell with that TASK line, put it on the clipboard and show it in a box.
copy_cell() {
  local task="$1" out="study/kaggle/.cell-to-paste.txt" line rule
  sed "s|^TASK = .*|TASK = \"$task\"|" study/kaggle/notebook_cell.txt > "$out"
  rule=$(printf '─%.0s' {1..72})
  gap
  printf '  %s┌%s%s\n' "$DIM" "$rule" "$RESET"
  while IFS= read -r line; do
    if [[ "$line" == TASK* ]]; then
      printf '  %s│%s %s%s%s\n' "$DIM" "$RESET" "$BOLD$YELLOW" "$line" "$RESET"
    else
      printf '  %s│ %s%s\n' "$DIM" "$line" "$RESET"
    fi
  done < "$out"
  printf '  %s└%s%s\n' "$DIM" "$rule" "$RESET"
  if clipboard < "$out" 2>/dev/null; then
    ok "This cell is copied to your clipboard. The highlighted TASK line is this session's job."
  else
    warn "Could not copy to the clipboard. Open $out, select all and copy it yourself."
  fi
}

# ask_url KEY "Prompt": a Kaggle notebook address, asked again until it looks like one.
ask_url() {
  while :; do
    ask "$1" "$2"
    local v="${!1}"
    v="${v%%\?*}"; v="${v%/edit}"; v="${v%/}"
    if [[ "$v" =~ ^https://(www\.)?kaggle\.com/code/[^/]+/[^/]+$ ]]; then
      printf -v "$1" '%s' "$v"
      saved "$1" "$v"
      return
    fi
    warn "That is not a notebook address. It looks like https://www.kaggle.com/code/<you>/<notebook-name>"
  done
}

# ensure_cli: the Kaggle CLI, installed and signed in.
ensure_cli() {
  if [[ -z "${KAGGLE_TOKEN:-}" ]]; then
    heading "First, connect the wizard to Kaggle (once)."
    ask_token
  fi
  install_cli
}

# notebook_running URL: true while the notebook's newest version is queued or running.
notebook_running() {
  local s
  s=$(kaggle_cli kernels status "$(notebook_ref "$1")" 2>&1) || return 1
  [[ "$s" == *QUEUED* || "$s" == *RUNNING* || "$s" == *NEW_SCRIPT* ]]
}

# peek_stamp URL: the session id in the stamp of the notebook's newest version, or "none" (no stamp: older code).
peek_stamp() {
  local d id=none
  d=$(mktemp -d)
  kaggle_cli kernels output "$(notebook_ref "$1")" -p "$d" --file-pattern '^bring-home/session_stamp\.json$' -o -q >/dev/null 2>&1 || true
  if [[ -f "$d/bring-home/session_stamp.json" ]]; then
    id=$(helper read-stamp "$d"); id="${id//$'\r'/}"; id="${id%% *}"
  fi
  rm -rf "$d"
  printf '%s' "$id"
}

# fetch_output KEY URL "re-run command": check that the notebook's newest version has finished, then download its
# bring-home folder into a new folder under study/kaggle/.downloads and put that folder's path in KEY. A version
# that saved no bring-home (it stopped early, under older session code) leaves KEY empty instead of stopping the
# wizard: the wizard then runs the next session in the same notebook.
fetch_output() {
  local ref status dir
  ref=$(notebook_ref "$2")
  ensure_cli
  gap
  say "Asking Kaggle about $(key "$ref")..."
  if ! status=$(kaggle_cli kernels status "$ref" 2>&1); then
    bad "Kaggle did not answer:"
    printf '%s\n' "$status" | sed 's/^/      /'
    why "Check your Internet connection. If the token was deleted or expired, run: bash study/kaggle/wizard.sh token"
    stuck; exit 1
  fi
  case "$status" in
    *QUEUED*|*RUNNING*|*NEW_SCRIPT*)
      gap
      say "The session is still running. Come back later and run the same command:"
      say "    $(key "$3")"
      exit 0 ;;
    *COMPLETE*)
      ok "The session has finished." ;;
    *)
      warn "The session did not finish normally. Kaggle says:"
      printf '%s\n' "$status" | sed 's/^/      /'
      why "The wizard still looks for what it saved." ;;
  esac
  dir="study/kaggle/.downloads/$(date +%Y%m%d-%H%M%S)-${ref#*/}"
  mkdir -p "$dir"
  say "Downloading its results..."
  if ! kaggle_cli kernels output "$ref" -p "$dir" --file-pattern '^bring-home/' -o -q >/dev/null; then
    rm -rf "$dir"; warn "Kaggle has no output for this version."
    printf -v "$1" '%s' ""; return 0
  fi
  # Kaggle keeps the folder in output file names. The CLI also writes the version's log (<notebook>.log) next to the
  # download, so a version without a bring-home still leaves a file here: never take that for a sign to fetch more.
  if [[ ! -d "$dir/bring-home" ]]; then
    rm -rf "$dir"; warn "This version saved no results (no bring-home folder)."
    printf -v "$1" '%s' ""; return 0
  fi
  ok "Downloaded to $dir"
  printf -v "$1" '%s' "$dir"
}

# ask_token: ask for a Kaggle API token until the CLI can see notebook A with it, then save it.
ask_token() {
  local out
  install_cli
  open_url "https://www.kaggle.com/settings/api"
  num 1 "Under $(key API), click $(key 'Generate New Token'). Copy the token Kaggle shows."
  more "Not $(key 'Create Legacy API Key'): that one downloads a file instead."
  num 2 "Paste it below. It stays hidden while you paste and is saved only on this computer."
  gap
  while :; do
    ask_secret KAGGLE_TOKEN "Token:"
    if out=$(kaggle_cli kernels status "$(notebook_ref "$NOTEBOOK_A")" 2>&1); then break; fi
    printf '%s\n' "$out" | sed 's/^/      /'
    warn "Kaggle did not accept that token. Generate a new one and paste it again."
  done
  remember KAGGLE_TOKEN "$KAGGLE_TOKEN"
  ok "The wizard can see your notebook $(key "uav-$KAGGLE_WHO-a"). It downloads results by itself from now on."
}

# ask_mirror: the folder that gets a copy of every checkpoint.
ask_mirror() {
  heading "Where should your copies of the checkpoints go?"
  why "Every checkpoint is also copied to your computer, so no Kaggle account holds the only copy."
  why "Best: a folder inside Google Drive or OneDrive, so the copy is off your laptop too."
  gap
  KAGGLE_MIRROR=""
  read -e -r -p "  ${BOLD}Folder (press Enter for $HOME/uav-yolo-checkpoints):${RESET} " KAGGLE_MIRROR || true
  KAGGLE_MIRROR="${KAGGLE_MIRROR//\'/}"; KAGGLE_MIRROR="${KAGGLE_MIRROR//\"/}"
  [[ -n "$KAGGLE_MIRROR" ]] || KAGGLE_MIRROR="$HOME/uav-yolo-checkpoints"
  mkdir -p "$KAGGLE_MIRROR"
  saved KAGGLE_MIRROR "$KAGGLE_MIRROR"
}

# notebook_settings: the two settings every session depends on, each confirmed.
notebook_settings() {
  num "$1" "Open the panel on the right side of the editor."
  more "Hidden? Click the small arrow at the right edge of the page."
  num "$(( $1 + 1 ))" "Under $(key 'Session options'), set $(key 'Accelerator') to $(key 'GPU T4 x2')."
  more "Not P100: it cannot run this study's software."
  num "$(( $1 + 2 ))" "Under $(key 'Session options'), switch $(key 'Internet') ON."
  more "No Internet switch? Your phone is not verified yet (stage 3)."
  must "Accelerator shows GPU T4 x2 and Internet is ON?"
}

# save_and_run "version name" FIRST_STEP_NUMBER: paste the cell and start the commit.
save_and_run() {
  num "$2" "In the notebook, click inside the code cell. Press $(key Ctrl+A), then $(key Ctrl+V) to paste."
  more "(Mac: Cmd+A, Cmd+V.) The notebook must contain only this one cell: delete any others."
  num "$(( $2 + 1 ))" "Top right: click $(key 'Save Version')."
  num "$(( $2 + 2 ))" "Name the version $(key "$1"). Choose $(key 'Save & Run All (Commit)'), not Quick Save. Click $(key Save)."
  must "Does Kaggle show the version as running (or queued)?"
  gap
  ok "It now runs on Kaggle by itself. You can close the browser and the laptop."
  why "It uses your weekly GPU quota (~30 h, resets Saturday 05:30 IST) only while it runs."
  why "Do not open an interactive GPU session at the same time."
}

stuck() { gap; why "Stuck? Take a screenshot and send it to Krishna. Guide: $GUIDE_URL"; }

